{"cmd":"@'
import subprocess
import numpy as np
from faster_whisper import WhisperModel
model = WhisperModel('medium.en', device='cpu', compute_type='int8', cpu_threads=9)
ranges = [(1190,1378),(1434,1473),(1613,1654),(2443,2499),(4620,4678),(5194,5237),(5285,5351)]
for start,end in ranges:
    for point in range(start,end,23):
        data = subprocess.check_output(['ffmpeg','-v','error','-ss',str(point),'-i','input/source.mp4','-t',str(min(24.5,end-point)),'-vn','-ac','1','-ar','16000','-f','f32le','pipe:1'])
        speech,_ = model.transcribe(np.frombuffer(data,dtype=np.float32),language='en',condition_on_previous_text=False,beam_size=4)
        for line in speech:
            print(round(point+line.start,2),round(point+line.end,2),line.text,flush=True)
'@ | python - | Tee-Object -FilePath work/detail.txt","yield_time_ms":1000,"max_output_tokens":1200}

{"cmd":"$map = (Get-Content -Raw -Encoding UTF8 submission/source_map.json | ConvertFrom-Json).segments
$previous = 0.0
$covered = 0.0
foreach ($entry in $map) {
 if ($entry.output_start_s -ne $previous) { throw 'Non-contiguous output mapping' }
 if ($null -ne $entry.source_start_s) {
  if (($entry.source_start_s -lt 0) -or ($entry.source_end_s -gt 5593.6) -or ([math]::Abs(($entry.source_end_s-$entry.source_start_s)-($entry.output_end_s-$entry.output_start_s)) -gt 0.001)) { throw 'Invalid source window' }
  $covered += $entry.output_end_s-$entry.output_start_s
 }
 $previous = $entry.output_end_s
}
[pscustomobject]@{Segments=$map.Count;OutputSeconds=$previous;SourceVideoSeconds=$covered;Coverage=[math]::Round(100*$covered/$previous,3);OriginalWindows=($map | Where-Object audio -eq original_dialogue).Count}
$cues = (Get-Content -Raw -Encoding UTF8 submission/subtitles.srt).Trim() -split '\r?\n\r?\n'
$maxWidth = 0
$priorEnd = 0.0
foreach ($cue in $cues) {
 $lines = $cue -split '\r?\n'
 $times = $lines[1] -split ' --> ' | ForEach-Object { [TimeSpan]::Parse($_.Replace(',','.')).TotalSeconds }
 if ($times[0] -lt $priorEnd -or $times[0] -ge $times[1] -or $times[1] -gt $previous) { throw 'Invalid subtitle interval' }
 $priorEnd = $times[1]
 $maxWidth = [math]::Max($maxWidth,($lines | Select-Object -Skip 2 | ForEach-Object Length | Measure-Object -Maximum).Maximum)
}
[pscustomobject]@{SubtitleCues=$cues.Count;MaxLineCharacters=$maxWidth}","max_output_tokens":1800}

{"cmd":"$timeline = (Get-Content -Raw -Encoding UTF8 submission/source_map.json | ConvertFrom-Json).segments
$previous = 0.0
$covered = 0.0
foreach ($entry in $timeline) {
 if ($entry.output_start_s -ne $previous -or $entry.output_end_s -le $previous) { throw 'Non-contiguous output mapping' }
 if ($null -ne $entry.source_start_s) {
  if ($entry.source_start_s -lt 0 -or $entry.source_end_s -gt 5593.6 -or [math]::Abs(($entry.source_end_s-$entry.source_start_s)-($entry.output_end_s-$entry.output_start_s)) -gt 0.001) { throw 'Invalid source interval' }
  $covered += $entry.output_end_s-$entry.output_start_s
 }
 $previous = $entry.output_end_s
}
$cues = (Get-Content -Raw -Encoding UTF8 submission/subtitles.srt).Trim() -split '\r?\n\r?\n'
$priorEnd = 0.0
$maxWidth = 0
for ($index=0; $index -lt $cues.Count; $index++) {
 $lines = $cues[$index] -split '\r?\n'
 $times = $lines[1] -split ' --> ' | ForEach-Object { [TimeSpan]::Parse($_.Replace(',','.')).TotalSeconds }
 if ([int]$lines[0] -ne $index+1 -or $times[0] -lt $priorEnd -or $times[0] -ge $times[1] -or $times[1] -gt $previous) { throw 'Invalid subtitle interval' }
 $priorEnd = $times[1]
 $maxWidth = [math]::Max($maxWidth,($lines | Select-Object -Skip 2 | ForEach-Object Length | Measure-Object -Maximum).Maximum)
}
[pscustomobject]@{Segments=$timeline.Count;OutputSeconds=$previous;SourceCoveragePct=[math]::Round(100*$covered/$previous,2);OriginalDialogues=($timeline | Where-Object audio -eq original_dialogue).Count;SubtitleCues=$cues.Count;MaxLineChars=$maxWidth}","max_output_tokens":1400}

{"cmd":"$info = ffprobe -v error -show_entries stream=codec_name,width,height,duration,nb_frames,channels:format=duration,size -of json submission/commentary.mp4 | ConvertFrom-Json
$mapping=(Get-Content -Raw -Encoding UTF8 submission/source_map.json | ConvertFrom-Json).segments
$end=$mapping[-1].output_end_s
if ($info.streams[0].codec_name -ne 'h264' -or $info.streams[1].codec_name -ne 'aac' -or [double]$info.streams[0].duration -ne $end -or [double]$info.streams[1].duration -ne $end -or [int]$info.streams[0].nb_frames -ne [math]::Round(25*$end)) { throw 'Final mux differs from timeline' }
$info | ConvertTo-Json -Depth 4
Get-ChildItem submission | Format-Table Name,Length","max_output_tokens":2000}
